<?php
namespace App\Http\Controllers;
use App\Models\EmployeeLeaveBalance; use App\Models\LeaveRequest; use App\Models\LeaveType; use App\Services\WorkforceAuditService; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class LeaveManagementController {
 public function index(){ $requests=LeaveRequest::with(['employee','leaveType'])->latest()->paginate(30); $balances=EmployeeLeaveBalance::with(['employee','leaveType'])->where('year',now()->year)->orderBy('employee_id')->limit(100)->get(); return view('workforce.leave.index',compact('requests','balances')); }
 public function store(Request $r, WorkforceAuditService $audit){$d=$r->validate(['employee_id'=>'required|exists:employees,id','leave_type_id'=>'required|exists:leave_types,id','start_date'=>'required|date','end_date'=>'required|date|after_or_equal:start_date','days'=>'required|numeric|min:0.5','portion'=>'required|in:full,first_half,second_half','reason'=>'nullable|string|max:1500']);$type=LeaveType::findOrFail($d['leave_type_id']); if($d['portion']!=='full' && !$type->allow_half_day) abort(422,'This leave type does not allow half-day requests.'); $balance=EmployeeLeaveBalance::firstOrCreate(['employee_id'=>$d['employee_id'],'leave_type_id'=>$d['leave_type_id'],'year'=>(int)date('Y',strtotime($d['start_date']))],['opening_balance'=>0,'accrued'=>$type->annual_entitlement,'used'=>0,'adjusted'=>0]); if($type->is_paid && $balance->available() < (float)$d['days']) abort(422,'Insufficient leave balance.'); $d['requested_by']=auth()->id();$m=LeaveRequest::create($d);$audit->model('created',$m,'Leave request created');return back()->with('success','Leave request created.');}
 public function decide(Request $r, LeaveRequest $leave, WorkforceAuditService $audit){$d=$r->validate(['action'=>'required|in:approve,reject','decision_note'=>'nullable|string|max:1000']);$old=$leave->toArray();DB::transaction(function()use($leave,$d){$new=$d['action']==='approve'?'approved':'rejected';$leave->update(['status'=>$new,'approved_by'=>auth()->id(),'approved_at'=>now(),'decision_note'=>$d['decision_note']??null]);if($new==='approved'){$balance=EmployeeLeaveBalance::firstOrCreate(['employee_id'=>$leave->employee_id,'leave_type_id'=>$leave->leave_type_id,'year'=>(int)$leave->start_date->format('Y')],['opening_balance'=>0,'accrued'=>$leave->leaveType?->annual_entitlement??0,'used'=>0,'adjusted'=>0]);abort_if($leave->leaveType?->is_paid && $balance->available() < (float)$leave->days,422,'Insufficient leave balance at approval.');$balance->increment('used',(float)$leave->days);}});$audit->model('updated',$leave,'Leave request decision',$old);return back()->with('success','Leave decision recorded.');}
}
